  'guard-settings.ajoute-un-bruit-leger-stable-sur-un-site': 'Adds light noise, stable on a site during the session, to what a page reads from a canvas, WebGL and audio; reduces the figures reported by navigator; hides the Mac’s addresses from WebRTC. May break sites.',
  'guard-settings.un-bruit-leger-sur-ce-qu-une-page-lit-de': 'Light noise on what a page reads from your device; may break sites.',
  'guard-settings.applique-les-regles-js-redirect': 'Applies the lists’ +js(), $redirect, $removeparam and $csp rules with Lucium scripts: a list names a scriptlet, it never brings code. May break sites. This does not apply to YouTube: its player rules follow ad blocking even when this option is off.',
  'guard-settings.bloque-davantage-grace-aux-regles-avancees': 'Blocks more with the lists’ advanced rules; may break sites.',
  'guard-settings.demande-l-un-des-deux-blocages-ci-dessus': 'Requires one of the two blockers above: without it, no rule is applied. May break sites.',
  'guard-settings.ecran-arrondi-a-une-taille-courante-carte': 'Denser noise, on large canvases and long sounds too; screen rounded to a common size, generic graphics card, no list of installed fonts, 4 cores and 4 GB at most, shared workers removed. More sites may behave differently.',
  'guard-settings.brouille-davantage-l-empreinte-de-l-appareil': 'Blurs your device’s fingerprint further; more sites may not work properly.',
  'guard-settings.la-liste-est-pleine': 'The list is full.',
  'guard-settings.mode-strict-de-la-protection-contre-l-empreinte': 'Strict fingerprint protection mode',
  'guard-settings.protection-renforcee-des-pages': 'Fingerprint and extended rules',
  'guard-settings.protection-contre-l-empreinte-numerique': 'Fingerprinting protection',
  'guard-settings.s-applique-a-la-page-que-vous-ouvrez-au': 'Applies at the next load, to the page, to the frames it contains and to the scripts it runs in the background (workers). Shared workers are not covered: they stay available and read the real values of the Mac, except in strict mode, which removes them from protected pages. While an extension debugs a page, its frames and its workers are not protected. Private and guest windows follow these settings.',
  'guard-settings.s-applique-a-la-page-suivante-que-vous': 'Applies from the next page you open.',
  'guard-settings.scriptlets-et-regles-etendues-du-bloqueur': 'Blocker scriptlets and extended rules',
  'guard-settings.site-a-exclure-de-la-protection-contre-l': 'Site to exclude from fingerprint protection',
  'guard-settings.sites-sans-protection-contre-l-empreinte': 'Sites without fingerprint protection',
  'guard-settings.un-site-de-la-liste-couvre-aussi-ses-sous-domaines': 'A site in the list also covers its subdomains. Use it for a site that the protection stops from working (image editor, game, video call). The sites in the “Sites without blocking” list (Blocker) are also left alone by this protection.',
  'guest-settings.desactive-l-entree-et-son-raccourci': 'When off, the entry and its shortcut disappear. Guest windows already open stay until they are closed.',
  'guest-settings.profil-invite': 'Guest profile',
  'guest-settings.proposer-nouvelle-fenetre-invite-dans-le-menu': 'Offer “New Guest Window” in the File menu',
  'guest-settings.une-fenetre-invite-garde-une-session-en': 'A guest window keeps a session in memory, erased when it closes: no history, no cookies, no extensions, nothing from your Spaces, favorites, settings or permissions. It only follows your search engine, your shortcuts, your appearance (size, light or dark) and your protections. It does not look like a private window: it is called “Guest”. Downloaded files stay in the Downloads folder, and Settings cannot be opened from it.',
  'guest-window.fenetre-invite': 'guest window',
  'guest-window.fenetre-privee': 'private window',
