  'launch-refusal.message': 'The security sandbox of the engine can’t start on this computer.',
  'launch-refusal.cause-apparmor': 'Ubuntu 24.04 and later forbid an ordinary program to create the isolated space this sandbox is made of, unless an AppArmor rule allows it, and an AppImage can’t carry that rule. Lucium never starts without its sandbox.',
  'launch-refusal.cause-autre': 'This system doesn’t let an ordinary program create the isolated space this sandbox is made of (user namespaces are disabled or restricted). Lucium never starts without its sandbox.',
  'launch-refusal.conseil-apparmor': 'Install the .deb package of Lucium instead, which carries the rule it needs: the Download page explains how. An administrator can also allow these spaces on the computer with “sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0” (until the next restart).',
  'launch-refusal.conseil-autre': 'Allow unprivileged user namespaces on this computer (or ask its administrator to), then start Lucium again. The Download page lists the other forms of Lucium for Linux.',
