  'little-arc-settings.garder-ouvert-exempte': `The “Keep open” pin in the header exempts a ${little.s} from this archiving.`,
  'little-arc-settings.le-delai-avant-l-archivage-d-une-fenetre': `The delay before a forgotten ${little.s} is archived is set above, in “Close and archive forgotten ${little.p}”. ⌥⌘ is the only combination the engine lets us recognize: ⌥ alone downloads the link and ⇧ opens a Glance. ⇧⌘-click acts like a click on a link that opens a new tab: a ${little.s} for a link to another site when the first option is on, a tab otherwise. These options leave private windows and private tabs alone.`,
