  'lock-settings.une-fenetre-privee-laissee-seule-se-ferme-sur': 'A private window left alone (no click or key, or in the background) covers itself with the lock screen and asks for the phrase or Touch ID. Its tabs stay in memory, but their pages are closed until it is unlocked.',
  'lock-settings.c-est-un-verrou-de-l-interface-lucium': 'This is an interface lock: Lucium hides your tabs and puts their pages to sleep until the passphrase is entered. It does not encrypt your cookies, your profiles or the files in the data folder: anyone who can read this computer’s disk can read them. The passphrase is never saved, only a fingerprint of it, in the lock.json file of the data folder (left out of exports); if you forget it, delete that file (Help › Troubleshooting › Show Lucium Data).',
  'lock-settings.un-verrou-de-l-interface-vos-fichiers-ne': 'A lock on the interface: your files are not encrypted; anyone who can read the disk can read them.',
