  'menu-actions.a-votre-demande-seulement-le-chrome-web-store': 'Only when you ask: the download of a Lucium update (“Install”, or “Check for Updates…”), the Chrome Web Store, Mozilla’s translation models, a site’s search engine, watched pages, live folders, resuming a download, the images of a Markdown export, the proxy test, and the encrypted DNS server you choose.',
