  'menu-actions.faites-ce-que-vous-voulez-examiner-puis': 'Do whatever you want to examine, then choose Help › Troubleshooting › Stop and Save Trace again.',
  'menu-actions.la-liste-complete-avec-l-interrupteur-de-chaque': 'The full list, with the switch of each connection and its default, is in the README (section “Connections Lucium makes by itself”).',
  'menu-actions.la-trace-contient-les-adresses-des-pages-visitees': 'The trace contains the addresses of the pages visited while recording, tab titles and information about this computer. The Desktop is suggested, and your Mac may sync it: choose another folder if you prefer, and read the trace over before sharing it.',
  'menu-actions.la-trace-couvre-toutes-les-categories-d': 'The trace covers every category of engine events, with no filter. It may contain the addresses of the pages you have open, tab titles, file names and information about this computer. It is saved to the file you choose when you stop recording, and Lucium never sends it anywhere: read it over before sharing it. Recording can slow the browser down; stop it as soon as you have done what you want to examine.',
  'menu-actions.la-verification-des-mises-a-jour-a-echoue': 'Checking for updates failed',
  'menu-actions.la-verification-des-mises-a-jour-n-est-pas': 'Update checking isn’t set up',
  'menu-actions.les-mises-a-jour-se-font-a-la-main': 'Updates are done by hand',
  'menu-actions.vous-utilisez-lucium-current-telechargez-la-derniere': 'You’re using Lucium {current}. This version doesn’t look for updates by itself: to get the latest one, download it from lucium.app.',
  'menu-actions.ouvrir-la-page-telecharger': 'Open the Download Page',
  'menu-actions.le-javascript-d-une-retouche-est-restaure': 'The JavaScript of one Tweak is restored turned off: read it over, then turn it on in the Tweak editor for it to run.',
  'menu-actions.le-javascript-de-count-retouches-est-restaure': 'The JavaScript of {count} Tweaks is restored turned off: read it over, then turn it on in the editor of each Tweak for it to run.',
  'menu-actions.les-donnees-ne-se-restaurent-pas-depuis-une': 'Data can’t be restored from a private window: use a normal window.',
  'menu-actions.les-favoris-les-onglets-epingles-et-les': 'The favorites, pinned tabs and folders of each Space are written to a file that every browser can import.',
  'menu-actions.lucium-n-a-ni-compte-ni-synchronisation-ni': 'Lucium has no account, no sync and no telemetry: your tabs, Spaces, history and settings stay in the app’s data on this computer.',
  'menu-actions.lucium-est-a-jour': 'Lucium is up to date',
  'menu-actions.ouvrir-le-readme': 'Open README',
  'menu-actions.plus-tard': 'Later',
  'menu-actions.pour-verifier-une-page-de-versions-indiquez-l': 'To check a releases page, give the address of a “latest version” feed (https), signed with the key of this build, in the updateFeedUrl setting of Lucium’s data; from the sources, the LUCIUM_UPDATE_FEED variable works too.',
  'menu-actions.recherche-des-mises-a-jour': 'Checking for updates…',
  'menu-actions.restauration-impossible': 'Couldn’t restore',
  'menu-actions.restaurer': 'Restore',
  'menu-actions.restaurer-spaces-et-tabs': 'Restore {spaces} and {tabs}?',
  'menu-actions.restaurer-les-donnees': 'Restore Data',
  'menu-actions.saisissez-la-phrase-secrete-choisie-pour-ce': 'Enter the passphrase chosen for this file.',
  'menu-actions.sans-action-de-votre-part-partent-du-reseau': 'Without any action on your part, these go out over the network: the pages you open; the blocker’s filter lists, on by default (downloaded at first launch, then checked every hour); site icons, fetched from the sites themselves and shown by the sidebar; search suggestions, to your search engine, as you type; Lucium’s release file, with no cookie, at the update address built into the app (or the one you wrote), 20 s after launch then once a day, while “Check for updates automatically” is on (it is by default); and, in the DRM variant, Google’s component service at each launch (Widevine).',
  'menu-actions.telecharger-manuellement': 'Download Manually',
  'menu-actions.trace-impossible': 'Couldn’t record the trace',
  'menu-actions.vos-espaces-onglets-dossiers-favoris-retouches': 'Your current Spaces, tabs, folders, favorites, Tweaks and settings are replaced. The extensions loaded at startup, the native messaging hosts of another browser, the update address, the lock, the download folders, the proxy and the DNS stay those of this installation: a file from elsewhere doesn’t change them. Nor does it grant a site any permission (camera, microphone, location…): only its refusals are taken. History, cookies, passwords and user scripts aren’t in an export: they stay as they are here. The rules of your filter lists and the pictures and backgrounds of Spaces aren’t in it either: a file from another Mac comes back without them. A copy of the current state is kept beside the state file.',
  'menu-actions.surveiller-des-pages-les-commandes-par-adresse-et-la-recherche-des-mises-a-jour-restent': '“Watch pages”, “Commands by lucium:// address” and “Check for updates automatically” stay on or off as they are here. The pages to watch that the file lists are taken only if watching is off here: they then wait for you to turn it on.',
  'menu-actions.vous-utilisez-lucium-current-cette-version-n': 'You’re using Lucium {current}. This build carries no update address. ',
  'menu-actions.vous-utilisez-current-cette-version-n-installe-pas': 'You’re using {current}. This build doesn’t install updates itself: the download page opens in your browser.',
