  'passwords-settings.un-coffre-chiffre-sur-ce-mac-phrase-de': 'An encrypted vault on this computer (passphrase of at least {phraseMin} characters, AES-256 and scrypt), no account and no sync. A password is only filled in if you ask (File › Fill Username and Password, the command bar or the panel), on a page at the exact address of the login, over https (or http on this computer), never in a frame and never in a private window or tab. Lucium offers to save a password you typed, but never does it on its own. The vault locks after {minutes} minutes without use, when the Mac sleeps, when the screen locks and with the Lucium lock; it stays out of the export and of session copies. Pages already open when you turn the feature on must be reloaded for the save prompt to see them.',
