  'persistence-notices.lucium-n-arrive-pas-a-ecrire-file-reason-vos': 'Lucium can’t write “{file}” ({reason}). Your changes from this session stay in memory and Lucium tries again regularly; if the problem lasts (full disk, folder permissions), they’ll be lost when you quit.',
