  'persistence-notices.lucium-ne-garde-que-les-trois-mises-de-cote': 'Lucium only keeps the three most recent set-aside copies of each file.',
  'persistence-notices.lucium-ne-garde-que-les-trois-mises-de-cote-2': 'Lucium only keeps the three most recent set-aside copies of each kind.',
  'persistence-notices.cette-version-demarre-avec-fresh': 'This version starts with {fresh}.',
  'persistence-notices.copies-automatiques-impossibles': 'Automatic backups unavailable',
