  'persistence-notices.vos-espaces-ne-sont-plus-proteges': 'Your spaces and tabs are no longer protected by a passphrase. To turn the lock back on, choose a new passphrase in {settingsPath}.',
  'persistence-notices.des-copies-automatiques-de-vos-espaces-et-onglets': 'Automatic backups of your Spaces and tabs exist: the most recent is from {when}. To put it back: File menu › Sessions…, “Automatic backups” section.',
  'persistence-notices.des-donnees-neuves': 'fresh data',
  'persistence-notices.donnees-d-une-version-plus-recente-d-lucium': 'Data from a newer version of Lucium',
  'persistence-notices.impossible-de-lire-thing': 'Couldn’t read {thing}',
  'persistence-notices.l-historique-d-un-de-vos-profils': 'the history of one of your profiles',
  'persistence-notices.le-fichier-file-est-illisible-reason-et': 'The file “{file}” is unreadable ({reason}) and Lucium couldn’t set it aside ({moveError}). ',
  'persistence-notices.le-fichier-file-est-illisible-reason-il-n-a-pas': 'The file “{file}” is unreadable ({reason}). It wasn’t deleted; it was set aside here: “{backup}”. ',
  'persistence-notices.le-fichier-file-thing-a-ete-ecrit-par-une': 'The file “{file}” ({thing}) was written by a newer version of Lucium than this one ({reason}). It isn’t damaged or deleted; it was set aside as is here: “{backup}”. ',
  'persistence-notices.le-fichier-mis-de-cote-peut-etre-repare-a-la-main': 'The set-aside file can be repaired by hand. ',
  'persistence-notices.le-fichier-mis-de-cote-peut-etre-repare-aide': 'The set-aside file can be repaired by hand; Help › Restore Data… accepts a backup in the right format. ',
  'persistence-notices.lucium-a-demarre-avec-fresh': 'Lucium started with {fresh}.',
  'persistence-notices.lucium-demarre-avec-fresh-mais-n-ecrit-rien': 'Lucium starts with {fresh}, but writes nothing to this file while it’s there, so as not to overwrite it: the changes of this session won’t be saved. Check the permissions and the free space of Lucium’s data folder, then restart Lucium.',
  'persistence-notices.pour-retrouver-ces-donnees-relancez-la-version': 'To get this data back, start the newer version of Lucium again, then choose Help › Restore Data… and this file. ',
  'persistence-notices.lucium-running-est-plus-ancien-que-la-version': 'Lucium {running} is older than the version that saved your data',
  'persistence-notices.vos-donnees-ont-ete-enregistrees-par-lucium-writer': 'Your Spaces, tabs and settings were saved by Lucium {writer}, a newer version than this one ({running}). Before touching them, Lucium kept a copy here: “{copy}”.',
  'persistence-notices.cette-version-peut-ne-pas-connaitre': 'This version may not know everything this file holds, and it doesn’t keep what it doesn’t know. To get it back, return to Lucium {writer} or a newer version, then choose Help › Restore Data… and this copy. ',
  'persistence-notices.lucium-ne-garde-que-les-trois-copies-de-cette-sorte': 'Lucium only keeps the three most recent copies of this kind.',
  'persistence-notices.vos-donnees-ont-ete-enregistrees-par-lucium-writer-sans-copie': 'Your Spaces, tabs and settings were saved by Lucium {writer}, a newer version than this one ({running}). Lucium couldn’t make a copy of them ({reason}).',
  'persistence-notices.pour-ne-rien-perdre-cette-version-n-ecrit-rien': 'So that nothing is lost, this version writes nothing to “{file}”: what you change during this session won’t be saved. Free up disk space or check the permissions of the data folder, then restart Lucium, or return to Lucium {writer}.',
  'persistence-notices.une-copie-de-vos-donnees-peut-etre-reprise': 'A copy of your data can be brought back',
  'persistence-notices.avant-votre-retour-a-une-version-plus-ancienne': 'You used an older version of Lucium, which may not have kept everything in your Spaces, tabs and settings. Before it touched them, Lucium had kept a copy here: “{copy}”.',
  'persistence-notices.pour-reprendre-cette-copie': 'To bring it back, choose Help › Restore Data… and this file. What you have changed since will be replaced; Lucium keeps a copy of it before restoring.',
  'persistence-notices.un-historique-vide': 'an empty history',
  'persistence-notices.vos-donnees-et-vos-reglages-ne-sont-pas-touches': 'Your data and settings are untouched, but no backup will be kept while the problem lasts (full disk, folder permissions). Lucium tries again at each scheduled backup.',
