  'settings.choisissez-ou-les-liens-s-ouvrent-dans': 'Send links from certain sites to a Space',
  'settings.clair-sombre-ou-celle-du-systeme-pour-les': 'Light, dark or the Mac’s, for Lucium itself: the Settings, the sidebar, the panels and all its windows. Websites follow it as long as “Appearance asked of websites” stays on Automatic. A Space whose theme is set to Light or Dark keeps its own in the sidebar. The same choice as View › Appearance › Lucium appearance in the menu bar.',
  'settings.clair-sombre-ou-comme-le-mac-pour-les': 'Light, dark or like the Mac, for Lucium’s windows and panels.',
  'settings.apparence-demandee-aux-sites': 'Appearance asked of websites',
  'settings.apparence-demandee-aux-sites-hint': 'Tells web pages whether to show their light or dark theme: this is what they read as the Mac’s theme preference. Automatic: websites follow Lucium. It never changes Lucium itself; to recolor a page that has no dark theme, see “Page Contrast”. The same choice as View › Appearance › Appearance asked of websites in the menu bar.',
  'settings.le-theme-clair-ou-sombre-que-les-sites': 'The light or dark theme websites are asked for; Automatic follows Lucium.',
  'settings.comme-le-defaut': 'Follow the default profile',
  'settings.bloqueur': 'Blocker',
