  'settings.par-defaut-lucium-les-ouvre-au-premier': `When off, these links open in the foreground. To another site, they open in a ${little.s} while “Open links that open a new tab in a ${little.s}” is on.`,
  'settings.un-lien-prevu-pour-un-nouvel-onglet-s-ouvre': 'A link meant for a new tab opens behind the page on screen.',
  'settings.le-coup-d-oeil-affiche-un-lien-par-dessus-la-page': 'Glance shows a link over the page without opening a tab; Esc closes it.',
  'settings.mise-en-veille': 'Sleep',
  'settings.permet-a-une-extension-comme-claude-de': 'Lets an extension such as Claude reach the app it installed for another browser (Claude Code, the Claude app). Lucium then launches those programs: if that other browser and Lucium are open with the same extension, the link may go to one or the other. Takes effect the next time the extension starts.',
