  'site-privacy-settings.cette-adresse-de-site-n-est-pas-valide': 'This site address isn’t valid.',
  'site-privacy-settings.desactive-par-defaut-quand-le-dernier': 'Off by default. When the last tab of a site in the list closes or is archived, even automatically (not when it navigates to another site), its data is cleared for the types checked in “Clear Site Data…” (⇧⌘X): all of them by default, cache and site history included, without touching extensions. Each entry covers the host shown, with its subdomains if that option is checked in this pane.',
  'site-privacy-settings.ce-qui-est-efface-suit-les-choix-de-effacer-en-bref': 'What is cleared follows the choices of “Clear Site Data…”.',
  'site-privacy-settings.effacer-a-la-fermeture-du-dernier-onglet-du-site': 'Clear when the site’s last tab closes',
  'site-privacy-settings.effacer-les-donnees-de-ces-sites-a-la-fermeture': 'Clear these sites’ data on close',
  'site-privacy-settings.electron-laisse-tout-demarrer-seul': 'Electron lets everything start on its own; Lucium applies the engine’s policy by default. The policy is fixed when the page is created: a change applies to new tabs and to a tab’s page at its next load. A muted video can still start on its own; the engine does not allow preventing it.',
  'site-privacy-settings.un-changement-s-applique-aux-nouveaux': 'A change applies to new tabs, and to the others at their next load.',
