  'settings.quand-vous-actualisez-tous-les-onglets-ceux-en': 'Applies to View › Reload All Tabs, its shortcut and the command bar: sleeping tabs are also woken, reloaded, then put back to sleep, except tabs exempt from sleep. With many tabs this takes several minutes, while a sleeping tab reloads anyway when you open it; it is mostly useful to find the sites that no longer respond. When off, only awake tabs are reloaded, in a few seconds, and a notice offers the others. The sidebar buttons always reload every tab, sleeping ones included.',
