  'settings-shortcuts.raccourcis-du-systeme-repris': 'A few shortcuts take a key macOS usually gives another command: ⌘S hides the sidebar (it does not save the page), ⌘; stops loading (instead of checking spelling), ⌃D turns on the site’s developer mode (and no longer deletes the next character in a text field). ⌥⌘S and ⌥⇧⌘S capture the page. Each can be changed in {settingsPath}. ⌥⌘M annotates the page instead of minimizing all windows, and cannot be changed. A note under a shortcut says when macOS or sites use the same key.',
