  'discover.titre': 'Discover Lucium',
  'discover.intro': 'Everything Lucium can do, sorted by what you want to do. Each feature says where to find it and its shortcut, and lets you try it right away.',
  'discover.chercher-label': 'Search for a feature',
  'discover.chercher-placeholder': 'Search: “bookmarks”, “screenshot”, “password”…',
  'discover.taches-label': 'What do you want to do?',
  'discover.liste-label': 'Features',
  'discover.niveau-label': 'Level',
  'discover.niveau-tous': 'All',
  'discover.niveau-debut': 'Getting started',
  'discover.niveau-avance': 'Advanced',
  'discover.tache-tout': 'All',
  'discover.tache-aller-plus-vite': 'Go faster',
  'discover.tache-organiser': 'Organize my tabs',
  'discover.tache-lire': 'Read and work',
  'discover.tache-garder': 'Keep and capture',
  'discover.tache-concentrer': 'Stay focused',
  'discover.tache-proteger': 'Protect my privacy',
  'discover.nouveau': 'New',
  'discover.ou-label': 'Where:',
